mongodb:createCollection.mongodb:options:
{
    validator: {
        $jsonSchema: {
            bsonType: "object",
            required: ["_id", "order_id", "user_id", "status", "timestamp", "payment_amount"],
            properties: {
                _id: {
                    bsonType: "objectId"
                }
                order_id: {
                    bsonType: "int"
                },
                user_id: {
                    bsonType: "int"
                },
                status: {
                    bsonType: "string"
                },
                timestamp: {
                    bsonType: "date"
                },
                payment_amount: {
                    bsonType: "double"
                }
            }
        }
    },
    validationAction: "error",
    validationLevel: "strict"
}
